create extension if not exists pgcrypto;
create type public.listing_status as enum ('draft','scheduled','active','ended_no_bids','ended_with_winner','cancelled','removed');
create type public.delivery_mode as enum ('pickup','shipping','both');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, full_name text, phone_e164 text unique, phone_verified_at timestamptz, city text, state text, role text not null default 'user' check(role in ('user','moderator','admin')), seller_status text not null default 'none', strikes_count integer not null default 0, created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,active boolean not null default true,risk_level integer not null default 0);
create table public.listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id),category_id uuid references public.categories(id),title text not null,description text not null,condition text not null,defects_declared text,start_price_cents bigint not null check(start_price_cents>0),current_price_cents bigint not null check(current_price_cents>0),highest_bidder_id uuid references public.profiles(id),bid_count integer not null default 0,starts_at timestamptz,ends_at timestamptz,original_ends_at timestamptz,extensions_count integer not null default 0,status public.listing_status not null default 'draft',delivery_mode public.delivery_mode not null,city text not null,state text not null,slug text unique not null,created_at timestamptz not null default now());
create table public.bids(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id),bidder_id uuid not null references public.profiles(id),amount_cents bigint not null,kind text not null check(kind in ('manual','auto')),max_amount_cents bigint,created_at timestamptz not null default now());
create table public.proxy_bids(listing_id uuid not null references public.listings(id),bidder_id uuid not null references public.profiles(id),max_amount_cents bigint not null,primary key(listing_id,bidder_id));
create table public.orders(id uuid primary key default gen_random_uuid(),listing_id uuid unique not null references public.listings(id),buyer_id uuid not null references public.profiles(id),seller_id uuid not null references public.profiles(id),amount_cents bigint not null,fee_cents bigint not null,seller_net_cents bigint not null,status text not null default 'pending_payment',payment_due_at timestamptz,created_at timestamptz not null default now());
create table public.watchlist(user_id uuid references public.profiles(id),listing_id uuid references public.listings(id),created_at timestamptz default now(),primary key(user_id,listing_id));
create table public.app_config(key text primary key,value jsonb not null,updated_at timestamptz default now());
insert into public.app_config(key,value) values ('commission_bps','500'),('anti_sniping','{"window_seconds":120,"extension_seconds":120,"max_extensions":5}'),('payment_deadline_hours','48');
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.listings enable row level security;alter table public.bids enable row level security;alter table public.proxy_bids enable row level security;alter table public.orders enable row level security;alter table public.watchlist enable row level security;alter table public.app_config enable row level security;
create policy "public profiles readable" on public.profiles for select using (true);
create policy "own profile update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "categories public read" on public.categories for select using(active=true);
create policy "active listings public read" on public.listings for select using(status in ('active','ended_no_bids','ended_with_winner') or auth.uid()=seller_id);
create policy "seller creates listings" on public.listings for insert with check(auth.uid()=seller_id);
create policy "seller updates own prebid listing" on public.listings for update using(auth.uid()=seller_id and bid_count=0 and status in ('draft','scheduled','active'));
create policy "bids public read" on public.bids for select using(true);
create policy "proxy own read" on public.proxy_bids for select using(auth.uid()=bidder_id);
create policy "orders parties read" on public.orders for select using(auth.uid() in (buyer_id,seller_id));
create policy "watchlist own all" on public.watchlist for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "config public read" on public.app_config for select using(true);
create or replace function public.block_bid_mutation() returns trigger language plpgsql as $$ begin raise exception 'BIDS_IMMUTABLE'; end $$;
create trigger bids_no_update before update or delete on public.bids for each row execute function public.block_bid_mutation();
create or replace function public.place_bid(p_listing uuid,p_amount bigint,p_idempotency text) returns public.listings language plpgsql security definer set search_path=public as $$ declare l public.listings; inc bigint; begin select * into l from listings where id=p_listing for update; if l.id is null then raise exception 'LISTING_NOT_FOUND'; end if; if l.status<>'active' or l.ends_at<=now() then raise exception 'AUCTION_ENDED'; end if; if l.seller_id=auth.uid() then raise exception 'SELLER_CANNOT_BID'; end if; inc:=case when l.current_price_cents<=10000 then 200 when l.current_price_cents<=50000 then 500 else 1000 end; if p_amount<l.current_price_cents+inc then raise exception 'BID_TOO_LOW'; end if; insert into bids(listing_id,bidder_id,amount_cents,kind) values(p_listing,auth.uid(),p_amount,'manual'); update listings set current_price_cents=p_amount,highest_bidder_id=auth.uid(),bid_count=bid_count+1,ends_at=case when ends_at-now()<=interval '2 minutes' and extensions_count<5 then ends_at+interval '2 minutes' else ends_at end,extensions_count=case when ends_at-now()<=interval '2 minutes' and extensions_count<5 then extensions_count+1 else extensions_count end where id=p_listing returning * into l; return l; end $$;
revoke all on function public.place_bid(uuid,bigint,text) from public;grant execute on function public.place_bid(uuid,bigint,text) to authenticated;
